using System.Collections.Generic;using UnityEngine;
namespace Alterverse.Visuals{
public sealed class DimensionTowerShell:MonoBehaviour{
Transform root,head,muzzle;Renderer core;readonly List<Material> mats=new();Color energy;float flashUntil;MaterialPropertyBlock coreBlock;static readonly int EmissionColor=Shader.PropertyToID("_EmissionColor");
public Vector3 MuzzlePosition=>muzzle!=null?muzzle.position:transform.position+Vector3.up*1.5f;
public void Build(int team){if(root!=null)return;Renderer ph=GetComponent<Renderer>();if(ph!=null)ph.enabled=false;root=new GameObject("DF_ProductionBastion").transform;root.SetParent(transform,false);Vector3 s=transform.lossyScale;root.localScale=new Vector3(1/s.x,1/s.y,1/s.z);root.localPosition=new Vector3(0,(.12f-transform.position.y)/s.y,0);energy=team==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;Material metal=Mat(Color.Lerp(StylizedArtDirection.ArenaStone,StylizedArtDirection.Ink,.35f),.72f,.32f),armor=Mat(Color.Lerp(team==0?StylizedArtDirection.ZeroMid:StylizedArtDirection.LumenMid,StylizedArtDirection.ArenaStone,.5f),.62f,.4f),glow=Mat(energy,.1f,.65f,true);Disc("Foot",2.25f,.16f,.13f,metal);Disc("ArmorDeck",1.72f,.39f,.10f,armor);Ring("EnergyBelt",1.47f,.055f,.55f,glow);BuildButtresses(team,armor);head=new GameObject("DF_BastionHead").transform;head.SetParent(root,false);head.localPosition=Vector3.up*1.55f;head.localRotation=Quaternion.Euler(0,team==0?90:-90,0);GameObject housing=ProductionMeshFactory.MeshObject("DF_TurretHousing",head,ProductionMeshFactory.Disc(.72f,.24f,28),armor);housing.transform.localRotation=Quaternion.Euler(90,0,0);GameObject orb=ProductionMeshFactory.MeshObject("DF_BastionCore",head,ProductionMeshFactory.Ring(.38f,.13f,24,8),glow);orb.transform.localPosition=new Vector3(0,.1f,.42f);orb.transform.localRotation=Quaternion.Euler(90,0,0);core=orb.GetComponent<Renderer>();TubeOn(head,"BarrelL",new Vector3(-.25f,.05f,.48f),new Vector3(-.25f,.05f,1.18f),.075f,metal);TubeOn(head,"BarrelR",new Vector3(.25f,.05f,.48f),new Vector3(.25f,.05f,1.18f),.075f,metal);muzzle=new GameObject("DF_TowerMuzzle").transform;muzzle.SetParent(head,false);muzzle.localPosition=new Vector3(0,.05f,1.22f);}
void BuildButtresses(int team,Material armor)
{
// Broad load-bearing wedges replace the six thin decorative rods.
Vector3[] vertices={new(-.36f,.26f,.62f),new(.36f,.26f,.62f),new(.53f,.26f,1.62f),new(-.53f,.26f,1.62f),new(-.24f,1.32f,.52f),new(.24f,1.32f,.52f),new(.25f,.62f,1.29f),new(-.25f,.62f,1.29f)};
int[] triangles={0,4,5,0,5,1,1,5,6,1,6,2,2,6,7,2,7,3,3,7,4,3,4,0,4,7,6,4,6,5,0,1,2,0,2,3};
Mesh mesh=new(){name="DF_BastionButtress",vertices=vertices,triangles=triangles};mesh.RecalculateNormals();mesh.RecalculateBounds();
for(int i=0;i<3;i++){GameObject obj=ProductionMeshFactory.MeshObject("DF_BastionButtress",root,mesh,armor);obj.transform.localRotation=Quaternion.Euler(0,i*120+(team==0?14+i*7:0),team==0?(i-1)*6:0);if(team==0)obj.transform.localScale=new Vector3(1,1+(i-1)*.16f,1);}
}
public void AimAt(Vector3 target){if(head==null)return;Vector3 d=target-head.position;d.y=0;if(d.sqrMagnitude>.001f)head.rotation=Quaternion.LookRotation(d);}public void Fire(){flashUntil=Time.time+.12f;}
void Update(){if(core==null||Time.timeScale<=0)return;float p=Time.time<flashUntil?1f:.08f+.05f*Mathf.Sin(Time.time*2f);coreBlock??=new MaterialPropertyBlock();core.GetPropertyBlock(coreBlock);coreBlock.SetColor(EmissionColor,Color.Lerp(energy,Color.white,p)*1.55f);core.SetPropertyBlock(coreBlock);}
void Disc(string n,float r,float y,float h,Material m){GameObject g=ProductionMeshFactory.MeshObject("DF_Bastion"+n,root,ProductionMeshFactory.Disc(r,h,32),m);g.transform.localPosition=Vector3.up*y;}void Ring(string n,float r,float tube,float y,Material m){GameObject g=ProductionMeshFactory.MeshObject("DF_Bastion"+n,root,ProductionMeshFactory.Ring(r,tube,32,8),m);g.transform.localPosition=Vector3.up*y;}void Tube(string n,Vector3 a,Vector3 b,float r,Material m){ProductionMeshFactory.MeshObject("DF_Bastion"+n,root,ProductionMeshFactory.Tube(a,b,r,8),m);}void TubeOn(Transform p,string n,Vector3 a,Vector3 b,float r,Material m){ProductionMeshFactory.MeshObject("DF_Bastion"+n,p,ProductionMeshFactory.Tube(a,b,r,8),m);}
Material Mat(Color c,float met,float sm,bool em=false){Shader sh=Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard");Material m=new(sh);mats.Add(m);m.color=c;if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",c);if(m.HasProperty("_Metallic"))m.SetFloat("_Metallic",met);if(m.HasProperty("_Smoothness"))m.SetFloat("_Smoothness",sm);if(em){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",c*1.45f);}return m;}void OnDestroy(){var owned=new HashSet<Mesh>();if(root!=null)foreach(MeshFilter filter in root.GetComponentsInChildren<MeshFilter>())if(filter.sharedMesh!=null&&owned.Add(filter.sharedMesh))Destroy(filter.sharedMesh);foreach(Material m in mats)if(m!=null)Destroy(m);}
}}